// Helper: Tim thong tin day du ve topic, section cua 1 lesson_id
export function findLessonHierarchy(lessonId) {
  if (!lessonId) return null;
  const cleanId = String(lessonId).toLowerCase();
  for (const [topicId, topic] of Object.entries(CURRICULUM_TREE)) {
    for (const [sectionId, section] of Object.entries(topic.sections)) {
      const found = section.lessons.find(l => l.id === cleanId || String(l.order_index) === cleanId.replace('l', ''));
      if (found) {
        return {
          topicId,
          topicTitle: topic.title,
          sectionId,
          sectionTitle: section.title,
          lessonId: found.id,
          lessonTitle: found.title,
          orderIndex: found.order_index
        };
      }
    }
  }
  return null;
}

// Helper: Lay danh sach phang tat ca cac bai hoc
export function getAllLessons() {
  const list = [];
  for (const [topicId, topic] of Object.entries(CURRICULUM_TREE)) {
    for (const [sectionId, section] of Object.entries(topic.sections || {})) {
      for (const lesson of section.lessons || []) {
        list.push({
          id: lesson.id,
          orderIndex: lesson.order_index,
          title: lesson.title,
          topicId,
          sectionId
        });
      }
    }
  }
  return list;
}
